command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$main="0b3ba42fe528f31fa4d6978b11d58a8f50a884c1"
$candidate="11f18f850380fab7127985ee3045135f13dca90d"
$branch="work/verification-infra-simplify-20261005"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "candidate moved"}
$base=Join-Path $env:RUNNER_TEMP ("validation-infra-"+$env:GITHUB_RUN_ID)
$mainDir=$base+"-main"
$candidateDir=$base+"-candidate"
foreach($p in @($mainDir,$candidateDir)){if(Test-Path -LiteralPath $p){Remove-Item -LiteralPath $p -Recurse -Force}}
try{
  & git worktree add --detach $mainDir $main
  if($LASTEXITCODE -ne 0){throw "main worktree failed"}
  & git worktree add --detach $candidateDir $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  $env:PYTHONIOENCODING="utf-8"

  Write-Host "===== BASELINE_MAIN_SOURCE ====="
  & python -X utf8 (Join-Path $mainDir "tools\winui\run_checks.py") source
  if($LASTEXITCODE -ne 0){throw "baseline main source failed"}

  Write-Host "===== CANDIDATE_SOURCE ====="
  & python -X utf8 (Join-Path $candidateDir "tools\winui\run_checks.py") source
  if($LASTEXITCODE -ne 0){throw "candidate source failed"}

  Write-Host "===== CRITICAL_PYTHON_STATIC ====="
  $checker=Join-Path $candidateDir "tools\winui\check_python_static.py"
  $critical=@(
    (Join-Path $candidateDir "tools\winui\high_contrast_state.py"),
    (Join-Path $candidateDir "tools\winui\high_contrast_runner_setup.py"),
    (Join-Path $candidateDir "tools\winui\high_contrast_acceptance.py"),
    (Join-Path $candidateDir "tools\winui\runner_health.py"),
    (Join-Path $candidateDir "tests\winui\test_high_contrast_gui.py")
  )
  & python -X utf8 $checker @critical
  if($LASTEXITCODE -ne 0){throw "critical Python static check failed"}

  & python -X utf8 (Join-Path $candidateDir "tools\winui\high_contrast_runner_setup.py") --check
  if($LASTEXITCODE -ne 0){throw "High Contrast setup check failed"}
  & python -X utf8 (Join-Path $candidateDir "tools\winui\runner_health.py") --configuration Release --check
  if($LASTEXITCODE -ne 0){throw "runner health check failed"}

  & git -C $candidateDir diff --check ($main+".."+$candidate)
  if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}
  Write-Host "VALIDATION_INFRA_SOURCE_AND_HEALTH_PASS"
}finally{
  Set-Location -LiteralPath $repo
  foreach($p in @($candidateDir,$mainDir)){if(Test-Path -LiteralPath $p){& git worktree remove --force $p}}
  & git worktree prune
}
